@RestController
@RequestMapping("/api/v1/mobile/dashboard")
public class MobileDashboardBffController {

    private final UserClient userClient;
    private final InventoryClient inventoryClient;

    public MobileDashboardBffController(UserClient userClient, InventoryClient inventoryClient) {
        this.userClient = userClient;
        this.inventoryClient = inventoryClient;
    }

    @GetMapping
    public Mono<MobileDashboardResponse> getDashboard(@AuthenticationPrincipal Jwt jwt) {
        String userId = jwt.getSubject();

        Mono<UserProfileDto> userMono = userClient.getUserProfile(userId)
            .onErrorResume(ex -> Mono.just(UserProfileDto.fallback()));

        Mono<List<InventoryItemDto>> inventoryMono = inventoryClient.getFeaturedItems()
            .onErrorResume(ex -> Mono.just(Collections.emptyList()));

        return Mono.zip(userMono, inventoryMono, MobileDashboardResponse::new);
    }
}
